import { type ApiClient, type Row } from '@acme/dh-bindings';
/** The result of `method(params)`, asked once per page and shared (a failure is forgotten, so it is asked again). */
export declare function requestOnce<T>(client: ApiClient, method: string, params?: Record<string, unknown>): Promise<T>;
/** Forget requestOnce's answers for methods starting with `method`, so the next call asks again. */
export declare const forgetRequests: (method: string) => void;
/** The live rows of a published table filtered on the server (column = value), re-rendering on each update. */
export declare function useFilteredRows(table: string | null, where: Record<string, string>, columns: string[]): Row[] | null;
/** Request `method` every `ms` (and when params change); the latest result, and the last error. */
export declare function usePolled<T>(client: ApiClient | null, method: string, params: Record<string, unknown> | null, ms: number): {
    value: T | null;
    error: string | null;
};
